using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using System;
using System.Collections.Generic;
using UnityEngine.SceneManagement;
using UnityEngine.EventSystems;
using UnityEngine.InputSystem.UI;
using Object=UnityEngine.Object;
public static class GridShiftV6Setup {
 const string Folder="Assets/Generated/Experience6";
 [MenuItem("GridShift/Atualização 6.0/Configurar entregas e menu")]
 public static void Configure(){if(EditorApplication.isPlaying)throw new Exception("Saia do Play Mode.");Directory.CreateDirectory(Folder);Directory.CreateDirectory("Assets/Resources");AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var manager=Object.FindFirstObjectByType<DeliveryManager>();if(manager==null)manager=new GameObject("DeliveryOperations").AddComponent<DeliveryManager>();manager.traffic=Object.FindFirstObjectByType<TrafficManager>();if(manager.GetComponent<DeliveryPersistence>()==null)manager.gameObject.AddComponent<DeliveryPersistence>();var presentation=manager.GetComponent<DeliveryPresentation>();if(presentation==null)presentation=manager.gameObject.AddComponent<DeliveryPresentation>();presentation.vehicleMaterial=Material("FleetGold",new Color(1,.76f,.08f)*1.6f);presentation.destinationMaterial=Material("DestinationCyan",new Color(.1f,.9f,1)*1.6f);
  Catalog(manager);int layer=MapLayer();presentation.markerLayer=layer;foreach(var camera in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))camera.cullingMask=camera.GetComponent<MinimapCamera>()!=null?camera.cullingMask|(1<<layer):camera.cullingMask&~(1<<layer);foreach(var tablet in Object.FindObjectsByType<PortableTablet>(FindObjectsSortMode.None))tablet.pageZoom=200;EditorSceneManager.SaveScene(scene);
  string background=Folder+"/CityBackground.png";if(SystemInfo.graphicsDeviceType!=UnityEngine.Rendering.GraphicsDeviceType.Null){var go=new GameObject("MenuPhoto");var camera=go.AddComponent<Camera>();camera.transform.position=new Vector3(280,105,80);camera.transform.LookAt(new Vector3(245,-4.6f,245));camera.fieldOfView=55;var rt=new RenderTexture(1920,1080,24);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(background,image.EncodeToPNG());RenderTexture.active=old;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(image);Object.DestroyImmediate(go);AssetDatabase.ImportAsset(background);}
  var brand=AssetDatabase.LoadAssetAtPath<GridShiftBranding>("Assets/Resources/GridShiftBranding.asset");if(brand==null){brand=ScriptableObject.CreateInstance<GridShiftBranding>();AssetDatabase.CreateAsset(brand,"Assets/Resources/GridShiftBranding.asset");}brand.gs=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Sprites/Canvas/PC/Icons/GS.png");EditorUtility.SetDirty(brand);
  scene=EditorSceneManager.OpenScene("Assets/Scenes/Office.unity");foreach(var adapter in Object.FindObjectsByType<GridShiftUwbTerminal>(FindObjectsSortMode.None))adapter.pageZoom=200;foreach(var tablet in Object.FindObjectsByType<PortableTablet>(FindObjectsSortMode.None))tablet.pageZoom=200;foreach(var terminal in Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None))terminal.terminalFieldOfView=40;foreach(var camera in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))camera.cullingMask=camera.GetComponent<MinimapCamera>()!=null?camera.cullingMask|(1<<layer):camera.cullingMask&~(1<<layer);EditorSceneManager.SaveScene(scene);
  string menuPath="Assets/Scenes/MainMenu.unity";scene=File.Exists(menuPath)?EditorSceneManager.OpenScene(menuPath):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var menu=Object.FindFirstObjectByType<GridShiftMainMenu>();if(menu==null)menu=new GameObject("GridShiftMainMenu").AddComponent<GridShiftMainMenu>();menu.cityBackground=AssetDatabase.LoadAssetAtPath<Texture2D>(background);if(Object.FindFirstObjectByType<EventSystem>()==null){var es=new GameObject("EventSystem",typeof(EventSystem),typeof(InputSystemUIInputModule));es.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();}if(Object.FindFirstObjectByType<Camera>()==null){var camera=new GameObject("MenuCamera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.01f,.02f,.035f);}EditorSceneManager.SaveScene(scene,menuPath);
  var scenes=EditorBuildSettings.scenes.Where(s=>s.path!=menuPath).ToList();scenes.Insert(0,new EditorBuildSettingsScene(menuPath,true));EditorBuildSettings.scenes=scenes.ToArray();AssetDatabase.SaveAssets();File.WriteAllText("v6-setup.txt","Pontos validados: "+managerPointCount+"\nMainMenu como cena inicial; SampleScene e Office preservadas.\nModo local DEMO; nenhum endpoint do Urban Flow inventado.\nGS original disponível: 32x20; Urban Flow original ainda não fornecida.");
 }
 static int managerPointCount;
 public static void Batch(){Configure();EditorApplication.Exit(0);}
 static Material Material(string name,Color color){string path=Folder+"/"+name+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Unlit"));AssetDatabase.CreateAsset(material,path);}material.SetColor("_BaseColor",color);return material;}
 static int MapLayer(){var so=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);var layers=so.FindProperty("layers");int index=LayerMask.NameToLayer("DeliveryMap");if(index>=0)return index;for(int i=10;i<32;i++)if(string.IsNullOrEmpty(layers.GetArrayElementAtIndex(i).stringValue)){layers.GetArrayElementAtIndex(i).stringValue="DeliveryMap";so.ApplyModifiedPropertiesWithoutUndo();return i;}throw new Exception("Nenhuma layer livre para marcadores.");}
 static void Catalog(DeliveryManager manager){var previous=GameObject.Find("DeliveryPoints");if(previous!=null)Object.DestroyImmediate(previous);var root=new GameObject("DeliveryPoints");var routes=Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).Where(r=>r.Valida&&Vector3.Distance(r.pontos[0].position,r.pontos[1].position)>22).OrderBy(r=>r.name).ToArray();var buildings=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Building_")).OrderBy(r=>r.name).ToArray();var points=new List<DeliveryPoint>();
  foreach(var building in buildings){TrafficRoute best=null;Vector3 stop=Vector3.zero;float nearest=32*32;foreach(var route in routes){var a=route.pontos[0].position;var direction=(route.pontos[1].position-a).normalized;float maximum=Vector3.Distance(a,route.pontos[1].position)-6;if(route.GetParada(out var line,out _))maximum=Mathf.Min(maximum,Vector3.Dot(line-a,direction)-12);if(maximum<10)continue;float along=Mathf.Clamp(Vector3.Dot(building.bounds.center-a,direction),10,maximum);var candidate=a+direction*along;float distance=Vector3.ProjectOnPlane(candidate-building.bounds.center,Vector3.up).sqrMagnitude;if(distance>=nearest)continue;if(!Road(candidate,direction))continue;nearest=distance;best=route;stop=candidate;}
   if(best==null||points.Any(p=>Vector3.Distance(p.Stop,stop)<8))continue;var point=new GameObject("Delivery_"+building.name).AddComponent<DeliveryPoint>();point.transform.SetParent(root.transform,false);var directionToBuilding=Vector3.ProjectOnPlane(building.bounds.center-stop,Vector3.up).normalized;var marker=stop+directionToBuilding*6;var ground=Physics.RaycastAll(marker+Vector3.up*20,Vector3.down,40,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.GetComponentInParent<TrafficCar>()==null&&h.collider.name.IndexOf("Building",StringComparison.OrdinalIgnoreCase)<0).OrderBy(h=>h.distance).FirstOrDefault();point.transform.position=ground.collider!=null&&ground.point.y<stop.y+1?ground.point+Vector3.up*.03f:stop+Vector3.up*.15f;var at=new GameObject("VehicleStop").transform;at.SetParent(point.transform);at.position=stop;at.rotation=Quaternion.LookRotation((best.pontos[1].position-best.pontos[0].position).normalized);point.vehicleStop=at;point.route=best;point.segment=0;point.accessible=true;point.id="P-"+Hash128.Compute(building.name+stop.ToString("F2")).ToString().Substring(0,12);point.establishmentType=building.name.Contains("House")?"Residência":building.name.Contains("Shop")?"Comércio":"Prédio";point.displayName=point.establishmentType+" · "+building.name.Replace("Building_","").Replace('_',' ');points.Add(point);
  }
  if(points.Count<2)throw new Exception("Catálogo insuficiente: "+points.Count);var origin=points[0];foreach(var point in points)point.accessible=DeliveryRouting.Find(origin.route,point.route)!=null&&DeliveryRouting.Find(point.route,origin.route)!=null;manager.points=points.ToArray();managerPointCount=points.Count(p=>p.accessible);File.WriteAllLines("v6-points.txt",points.Select(p=>p.id+" | "+p.displayName+" | "+p.Stop+" | "+p.route.name+" | valid="+p.Valid));
 }
 static bool Road(Vector3 at,Vector3 direction){var hits=Physics.RaycastAll(at+Vector3.up*3,Vector3.down,8,~0,QueryTriggerInteraction.Ignore);if(!hits.Any(h=>h.collider.name.StartsWith("Road ")))return false;foreach(var c in Physics.OverlapBox(at+Vector3.up*1.6f,new Vector3(1.8f,1.1f,4.8f),Quaternion.LookRotation(direction),~0,QueryTriggerInteraction.Ignore))if(!c.name.StartsWith("Road ")&&c.GetComponentInParent<PlayerMovement>()==null)return false;return true;}
 public static void Audit(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var rows=Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).Where(r=>r.Valida).OrderBy(r=>r.name).Select(r=>r.name+" | "+r.pontos.Length+" | first="+r.pontos[0].position+" -> "+r.pontos[1].position+" | last="+r.pontos.Last().position+" | junction="+r.Cruzamento?.transform.position);File.WriteAllLines("v6-routes.txt",rows);File.WriteAllLines("v6-buildings.txt",Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.bounds.size.y>4&&r.bounds.size.x>3&&r.bounds.size.z>3).Select(r=>r.name+" | "+r.bounds));EditorApplication.Exit(0);}
}
